-- شمس ERP: financial core. Amounts are integer IQD and immutable financial events use status/reversal.
create extension if not exists pgcrypto;

create type public.record_status as enum ('active','draft','completed','cancelled','archived','reversed','suspended');
create type public.payment_method as enum ('cash','bank_transfer','pos','other');
create type public.installment_status as enum ('upcoming','due','partially_paid','paid','overdue','waived','archived');
create type public.financier_transaction_type as enum ('investment_deposit','contract_allocation','capital_return','profit_earned','settlement_payment','withdrawal','adjustment','reversal');

create table public.roles (id uuid primary key default gen_random_uuid(), code text unique not null, name_ar text not null, created_at timestamptz not null default now());
create table public.permissions (id uuid primary key default gen_random_uuid(), code text unique not null, name_ar text not null);
create table public.role_permissions (role_id uuid references public.roles(id) on delete cascade, permission_id uuid references public.permissions(id) on delete cascade, primary key(role_id, permission_id));
create table public.users (id uuid primary key references auth.users(id) on delete restrict, full_name text not null, role_id uuid references public.roles(id), status public.record_status not null default 'active', created_at timestamptz not null default now());
create table public.user_permissions (user_id uuid references public.users(id) on delete cascade, permission_id uuid references public.permissions(id) on delete cascade, granted boolean not null default true, primary key(user_id, permission_id));

create table public.customers (id uuid primary key default gen_random_uuid(), customer_number text unique not null, full_name text not null, phone text not null, alternative_phone text, address text, governorate text, district text, id_number text, notes text, status public.record_status not null default 'active', created_by uuid references public.users(id), created_at timestamptz not null default now());
create index customers_phone_idx on public.customers(phone);
create table public.products (id uuid primary key default gen_random_uuid(), sku text unique, name text not null, brand text, category text, model text, unit text not null default 'piece', cost_price bigint not null check(cost_price >= 0), selling_price bigint not null check(selling_price >= 0), stock_quantity integer, warranty text, description text, status public.record_status not null default 'active');

create table public.invoices (id uuid primary key default gen_random_uuid(), invoice_number text unique not null, customer_id uuid not null references public.customers(id), invoice_date date not null default current_date, sale_type text not null check(sale_type in ('direct','installment')), subtotal bigint not null check(subtotal >= 0), discount_amount bigint not null default 0 check(discount_amount >= 0), grand_total bigint not null check(grand_total >= 0), status public.record_status not null default 'draft', created_by uuid references public.users(id), created_at timestamptz not null default now());
create table public.invoice_items (id uuid primary key default gen_random_uuid(), invoice_id uuid not null references public.invoices(id) on delete restrict, product_id uuid references public.products(id), description text not null, quantity integer not null check(quantity > 0), unit_price bigint not null check(unit_price >= 0), discount_amount bigint not null default 0 check(discount_amount >= 0));

create table public.financiers (id uuid primary key default gen_random_uuid(), financier_number text unique not null, name text not null, phone text, address text, notes text, status public.record_status not null default 'active', created_at timestamptz not null default now());
create table public.financier_agreement_versions (id uuid primary key default gen_random_uuid(), financier_id uuid not null references public.financiers(id), version integer not null, agreement_type text not null check(agreement_type in ('fixed_profit','profit_percentage','custom')), allocation_strategy text not null check(allocation_strategy in ('capital_first','pro_rata','custom')), terms jsonb not null default '{}'::jsonb, effective_from date not null default current_date, unique(financier_id, version));
create table public.financier_investments (id uuid primary key default gen_random_uuid(), investment_number text unique not null, financier_id uuid not null references public.financiers(id), agreement_version_id uuid references public.financier_agreement_versions(id), amount bigint not null check(amount > 0), investment_date date not null default current_date, status public.record_status not null default 'active', created_at timestamptz not null default now());

create table public.contracts (id uuid primary key default gen_random_uuid(), contract_number text unique not null, customer_id uuid not null references public.customers(id), contract_date date not null default current_date, cash_price bigint not null check(cash_price >= 0), installment_price bigint not null check(installment_price >= 0), down_payment bigint not null default 0 check(down_payment >= 0), financed_amount bigint not null check(financed_amount >= 0), installment_count integer not null check(installment_count > 0), frequency_months integer not null default 1 check(frequency_months > 0), first_due_date date not null, final_due_date date, financier_id uuid references public.financiers(id), agreement_version_id uuid references public.financier_agreement_versions(id), agreement_snapshot jsonb, status public.record_status not null default 'draft', notes text, created_by uuid references public.users(id), created_at timestamptz not null default now());
create index contracts_customer_idx on public.contracts(customer_id);
create table public.contract_items (id uuid primary key default gen_random_uuid(), contract_id uuid not null references public.contracts(id) on delete restrict, product_id uuid references public.products(id), description text not null, quantity integer not null check(quantity > 0), cost_price bigint not null check(cost_price >= 0), selling_price bigint not null check(selling_price >= 0));
create table public.installments (id uuid primary key default gen_random_uuid(), contract_id uuid not null references public.contracts(id) on delete restrict, schedule_version integer not null default 1, installment_number integer not null, due_date date not null, original_amount bigint not null check(original_amount > 0), status public.installment_status not null default 'upcoming', archived_at timestamptz, unique(contract_id, schedule_version, installment_number));
create index installments_due_idx on public.installments(due_date) where status in ('upcoming','due','partially_paid','overdue');

create table public.payments (id uuid primary key default gen_random_uuid(), payment_number text unique not null, customer_id uuid not null references public.customers(id), contract_id uuid references public.contracts(id), invoice_id uuid references public.invoices(id), amount bigint not null check(amount > 0), payment_date timestamptz not null default now(), payment_method public.payment_method not null, status public.record_status not null default 'active', received_by uuid references public.users(id), notes text, reversal_of uuid references public.payments(id), created_at timestamptz not null default now(), check(contract_id is not null or invoice_id is not null));
create table public.payment_allocations (id uuid primary key default gen_random_uuid(), payment_id uuid not null references public.payments(id) on delete restrict, installment_id uuid references public.installments(id), invoice_id uuid references public.invoices(id), amount bigint not null check(amount > 0), check(installment_id is not null or invoice_id is not null));
create table public.receipts (id uuid primary key default gen_random_uuid(), receipt_number text unique not null, payment_id uuid unique not null references public.payments(id), issued_at timestamptz not null default now(), issued_by uuid references public.users(id));

create table public.financier_contract_allocations (id uuid primary key default gen_random_uuid(), contract_id uuid not null references public.contracts(id), investment_id uuid not null references public.financier_investments(id), capital_allocated bigint not null check(capital_allocated > 0), expected_return bigint, created_at timestamptz not null default now(), unique(contract_id, investment_id));
create table public.financier_transactions (id uuid primary key default gen_random_uuid(), financier_id uuid not null references public.financiers(id), investment_id uuid references public.financier_investments(id), contract_id uuid references public.contracts(id), payment_id uuid references public.payments(id), transaction_type public.financier_transaction_type not null, debit bigint not null default 0 check(debit >= 0), credit bigint not null default 0 check(credit >= 0), notes text, occurred_at timestamptz not null default now(), reversed_by uuid references public.financier_transactions(id), check(debit > 0 or credit > 0));
create index financier_ledger_idx on public.financier_transactions(financier_id, occurred_at desc);
create table public.financier_settlements (id uuid primary key default gen_random_uuid(), settlement_number text unique not null, financier_id uuid not null references public.financiers(id), from_date date not null, to_date date not null, total_payable bigint not null check(total_payable >= 0), status public.record_status not null default 'draft', approved_by uuid references public.users(id), created_at timestamptz not null default now(), check(to_date >= from_date));

create table public.expenses (id uuid primary key default gen_random_uuid(), expense_number text unique not null, category text not null, amount bigint not null check(amount > 0), expense_date date not null default current_date, payment_method public.payment_method not null, description text, attachment_path text, status public.record_status not null default 'active', created_by uuid references public.users(id), created_at timestamptz not null default now());
create table public.audit_logs (id bigint generated always as identity primary key, user_id uuid references public.users(id), action text not null, entity_type text not null, entity_id uuid, old_data jsonb, new_data jsonb, reason text, ip inet, user_agent text, created_at timestamptz not null default now());
create index audit_logs_entity_idx on public.audit_logs(entity_type, entity_id, created_at desc);
create table public.system_sequences (name text primary key, prefix text not null, year_scoped boolean not null default false, current_value bigint not null default 0, updated_at timestamptz not null default now());

alter table public.customers enable row level security; alter table public.contracts enable row level security; alter table public.payments enable row level security; alter table public.audit_logs enable row level security;
-- Application policies must call auth permission checks; financial writes are performed through SECURITY DEFINER RPCs only.
